export const ARTISTS = A.map(([id, name, genre, fame]) => ({ id: 'a' + id, name, genre, fame }));

// Song ids stay positional, exactly as the build assigned them.
export const SONGS = S.map(([title, type, year, ix], i) => ({ id: 's' + i, title, type, year, artists: ix.map((j) => ARTISTS[j].id) }));

